{"Table":"bk_tb_accounts","Create Table":"CREATE TABLE `bk_tb_accounts` (\n  `id` varchar(36) NOT NULL,\n  `name` varchar(255) NOT NULL,\n  `ammount` double NOT NULL,\n  `paymentType` varchar(255) NOT NULL,\n  `owner` varchar(255) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  `threshold` double NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_account_owner` (`owner`),\n  KEY `FK_account_payment_type` (`paymentType`),\n  CONSTRAINT `FK_account_owner` FOREIGN KEY (`owner`) REFERENCES `bk_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_account_payment_type` FOREIGN KEY (`paymentType`) REFERENCES `bk_tb_payments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"bk_tb_accounts.sql","path":"files/sql/rod/bk_tb_accounts.sql","sha":"ec5188fc47eb635da8529149d4a172c00f386050","size":1840,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/bk_tb_accounts.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/bk_tb_accounts.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/ec5188fc47eb635da8529149d4a172c00f386050","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/bk_tb_accounts.sql","type":"file","content":"eyJUYWJsZSI6ImJrX3RiX2FjY291bnRzIiwiQ3JlYXRlIFRhYmxlIjoiQ1JF\nQVRFIFRBQkxFIGBia190Yl9hY2NvdW50c2AgKFxuICBgaWRgIHZhcmNoYXIo\nMzYpIE5PVCBOVUxMLFxuICBgbmFtZWAgdmFyY2hhcigyNTUpIE5PVCBOVUxM\nLFxuICBgYW1tb3VudGAgZG91YmxlIE5PVCBOVUxMLFxuICBgcGF5bWVudFR5\ncGVgIHZhcmNoYXIoMjU1KSBOT1QgTlVMTCxcbiAgYG93bmVyYCB2YXJjaGFy\nKDI1NSkgTk9UIE5VTEwsXG4gIGBjcmVhdGVkX2F0YCB0aW1lc3RhbXAgTk9U\nIE5VTEwgREVGQVVMVCBjdXJyZW50X3RpbWVzdGFtcCgpLFxuICBgdXBkYXRl\nZF9hdGAgdGltZXN0YW1wIE5PVCBOVUxMIERFRkFVTFQgY3VycmVudF90aW1l\nc3RhbXAoKSBPTiBVUERBVEUgY3VycmVudF90aW1lc3